            entry( 121L, new GregorianCalendar( 2013, Calendar.JULY, 20 ).getTime() )
        );

        assertThat( source.getPublicValues() )
            .isNotNull()
            .hasSize( 2 )
            .contains(
                entry( 42L, new GregorianCalendar( 1980, Calendar.JANUARY, 1 ).getTime() ),
                entry( 121L, new GregorianCalendar( 2013, Calendar.JULY, 20 ).getTime() )
            );
    }

